import * as THREE from 'three/webgpu';
import { uv, mix, color, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color } = ctx.THREE;

  // Root container
  const root = new Group();
  root.name = 'brand-mark-wall';

  // ==== Gradient albedo node for tiles ====
  const albedoNode = mix(
    color(new Color('#1a1a22')),
    color(new Color('#121218')),
    uv().y
  );

  // ==== Tile material ====
  const tileMaterial = new MeshStandardNodeMaterial({
    colorNode: albedoNode,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.05,
    // Anisotropy (aligned to X)
    anisotropy: 0.6,
    anisotropyDirectionNode: vec3(1, 0, 0),
    transparent: true,
    opacity: 1,
  });

  // ==== Geometry ====
  const tileGeom = new PlaneGeometry(1.0, 0.62);

  // ==== Layout calculations ====
  const cols = 3;
  const rows = 2;
  const gap = 0.25; // base unit
  const tileW = 1.0;
  const tileH = 0.62;

  const totalW = cols * tileW + (cols - 1) * gap; // 3.5
  const totalH = rows * tileH + (rows - 1) * gap; // 1.49

  const startX = -totalW / 2 + tileW / 2; // -1.25
  const startY = totalH / 2 - tileH / 2; // 0.435

  // ==== Text items ====
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerItem = items[0];
  const brandItems = items.slice(1); // expect 6 items

  // ==== Kicker text (above the grid) ====
  if (kickerItem && kickerItem.text) {
    const kicker = ctx.fontAtlas.createText(kickerItem.text, {
      fontSize: kickerItem.typography?.fontSize ?? 9,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: (kickerItem.typography?.letterSpacing ?? 0) * 0.01,
    });
    kicker.position.set(0, startY + tileH / 2 + 0.3, 0.01);
    const mat = kicker.traverse((obj) => {
      if (obj.isMesh && obj.material) {
        obj.material.transparent = true;
        obj.material.opacity = 0.78;
      }
    });
    root.add(kicker);
  }

  // ==== Create tiles with brand wordmarks ====
  const timelines = [];
  const tileGroups = [];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c;
      const word = brandItems[idx]?.text ?? '';

      const tileGroup = new Group();
      tileGroup.name = `tile-${idx}`;
      tileGroup.position.set(startX + c * (tileW + gap), startY - r * (tileH + gap), 0);
      tileGroup.userData = {};

      // Mesh
      const mesh = new Mesh(tileGeom, tileMaterial.clone());
      mesh.renderOrder = 1;
      mesh.material.transparent = true;
      mesh.material.opacity = 0; // start invisible for fade-up
      tileGroup.add(mesh);

      // Text
      const txt = ctx.fontAtlas.createText(word, {
        fontSize: 13,
        color: '#e8ecf2',
        align: 'center',
        letterSpacingPx: 0.08 * 0.01,
      });
      txt.position.set(0, 0, 0.01);
      txt.traverse((obj) => {
        if (obj.isMesh && obj.material) {
          obj.material.transparent = true;
          obj.material.opacity = 0.78;
        }
      });
      tileGroup.add(txt);

      // ==== Hover interaction ====
      const hoverEnter = () => {
        const tl = gsap.timeline();
        tl.to(mesh.material, {
          opacity: 1,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        tl.to(txt.traverse((o) => (o.isMesh && o.material ? o.material : null)), {
          opacity: 1,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        }, 0);
        tl.to(tileGroup.position, {
          z: 0.05,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        }, 0);
        timelines.push(tl);
      };

      const hoverLeave = () => {
        const tl = gsap.timeline();
        tl.to(mesh.material, {
          opacity: 0,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        tl.to(txt.traverse((o) => (o.isMesh && o.material ? o.material : null)), {
          opacity: 0.78,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        }, 0);
        tl.to(tileGroup.position, {
          z: 0,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        }, 0);
        timelines.push(tl);
      };

      // Register handlers on root userData
      root.userData.handlers = root.userData.handlers || {};
      root.userData.handlers[`tile${idx}_hover`] = hoverEnter;
      root.userData.handlers[`tile${idx}_leave`] = hoverLeave;

      // ==== Initial entrance animation (staggered) ====
      const entrance = gsap.fromTo(
        tileGroup,
        { y: tileGroup.position.y + 0.2 },
        {
          y: tileGroup.position.y,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          delay: (idx * 0.08),
          onStart: () => {
            mesh.material.opacity = 0;
          },
          onUpdate: () => {
            // opacity driven by mesh material
          },
          onComplete: () => {
            mesh.material.opacity = 1;
          },
        }
      );
      timelines.push(entrance);

      root.add(tileGroup);
      tileGroups.push(tileGroup);
    }
  }

  // ==== Cleanup ====
  root.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl && tl.kill) tl.kill();
    });
    tileGroups.forEach((tg) => {
      tg.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (obj.material.map) obj.material.map.dispose();
            obj.material.dispose();
          }
        }
      });
    });
    if (tileMaterial) {
      if (tileMaterial.map) tileMaterial.map.dispose();
      tileMaterial.dispose();
    }
    if (tileGeom) tileGeom.dispose();
  };

  return root;
}
